export function editorMarkup(note){return `<article class="note-editor"><div class="note-editor-head"><div class="writing-modes" aria-label="Modo do documento"><button type="button" id="readMode" aria-pressed="false"><svg class="mode-eye-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M2.5 12s3.4-6 9.5-6 9.5 6 9.5 6-3.4 6-9.5 6-9.5-6-9.5-6Z"/><circle cx="12" cy="12" r="2.5"/></svg>Visualizar</button><button type="button" id="editMode" aria-pressed="true">✎ Editar</button></div><button id="expandEditor" class="focus-button" aria-label="Expandir editor" aria-expanded="false"><span>⛶</span><span class="focus-label">Expandir</span></button></div><div class="editor-toolbar" aria-label="Formatação de texto"><div class="tool-row"><select id="fontFamily" aria-label="Fonte"><option value="Arial">Sans</option><option value="Georgia">Serif</option><option value="Verdana">Verdana</option><option value="Courier New">Mono</option></select><input type="number" id="fontSize" aria-label="Tamanho da fonte" title="Tamanho da fonte em pixels" value="14" min="8" max="72" step="1">${tool('Negrito','<b>B</b>','data-format="bold"')}${tool('Itálico','<em>I</em>','data-format="italic"')}${tool('Sublinhado','<u>U</u>','data-format="underline"')}${tool('Tachado','<s>S</s>','data-format="strikeThrough"')}${tool('Sobrescrito','x<sup>2</sup>','data-format="superscript"')}${tool('Subscrito','x<sub>2</sub>','data-format="subscript"')}<span class="toolbar-divider"></span>${tool('Maiúsculas','Aʙ','data-case="upper"')}${tool('Minúsculas','aʙ','data-case="lower"')}${tool('Código inline','‹/›','id="inlineCode"')}${tool('Adicionar ou editar link','↗','id="linkButton"')}<details class="color-picker" id="colorPicker"><summary title="Cor do texto" aria-label="Cor do texto"><span class="color-symbol">A</span><span>⌄</span></summary><div class="color-panel"><div class="palette-tabs"><button type="button" data-palette="color" aria-pressed="true">Texto</button><button type="button" data-palette="background-color" aria-pressed="false">Fundo</button></div><div class="color-presets">${[['#4b7657','Floresta'],['#b39354','Dourado'],['#bc7279','Rosa'],['#7e9fbd','Azul'],['#a18eb4','Lavanda'],['#79a79b','Sálvia'],['#9ba59a','Pedra'],['#d4c9a4','Marfim']].map(([color,name])=>tool(name,'',`data-color="${color}" style="--swatch:${color}"`)).join('')}</div><button type="button" id="defaultColor" class="default-color">Cor padrão / sem fundo</button><label class="custom-color"><span>Personalizar</span><input type="color" id="textColor" value="#b39354" aria-label="Cor personalizada"></label></div></details>${tool('Marca-texto','▰','id="highlightButton"')}${tool('Limpar formatação','T×','id="clearFormatting"')}<span class="toolbar-divider"></span>${tool('Desfazer','↶','data-format="undo"')}${tool('Refazer','↷','data-format="redo"')}</div><div class="tool-row paragraph-tools"><select id="blockType" aria-label="Estilo do texto"><option value="p">¶ Parágrafo</option><option value="h1">H₁ Título 1</option><option value="h2">H₂ Título 2</option><option value="h3">H₃ Título 3</option><option value="blockquote">❞ Citação</option></select>${tool('Alinhar à esquerda','☰','data-format="justifyLeft"')}${tool('Centralizar','≡','data-format="justifyCenter"')}${tool('Alinhar à direita','☰','data-format="justifyRight" class="align-right-icon"')}${tool('Justificar','▤','data-format="justifyFull"')}<span class="toolbar-divider"></span>${tool('Lista com marcadores','• ≡','data-format="insertUnorderedList"')}${tool('Lista numerada','1 ≡','data-format="insertOrderedList"')}${tool('Checklist','☑','id="checklistButton"')}${tool('Aumentar recuo','›≡','data-format="indent"')}${tool('Diminuir recuo','‹≡','data-format="outdent"')}<select id="lineSpacing" aria-label="Espaçamento entre linhas"><option value="1">↕ 1</option><option value="1.25">↕ 1,25</option><option value="1.5">↕ 1,5</option><option value="1.75" selected>↕ 1,75</option><option value="2">↕ 2</option><option value="2.5">↕ 2,5</option></select>${tool('Citação','❞','data-block="blockquote"')}${tool('Separador','―','id="separatorButton"')}</div></div><div class="document-title-row"><button type="button" id="documentEmoji" class="document-emoji" aria-label="Escolher emoji do documento" title="Escolher emoji">${e(note.emoji||'＋')}</button><input class="note-title" id="noteTitle" value="${e(note.title)}" aria-label="Título do documento"></div><div id="emojiPicker" class="emoji-picker" hidden><span class="eyebrow">ÍCONE DA PÁGINA</span><div>${['📜','📖','🖋️','✨','🌿','🌙','🗺️','🏰','🧙','🐉','⚔️','👑','🦉','💎','🔥','🌊','🌸','☀️'].map(emoji=>tool(emoji,emoji,`data-emoji="${emoji}"`)).join('')}</div><label>Outro emoji <input id="customEmoji" aria-label="Emoji personalizado" maxlength="12" placeholder="✧"></label><button type="button" id="removeEmoji">Remover ícone</button></div><div id="editor" class="editable" contenteditable="true" role="textbox" aria-multiline="true" aria-label="Conteúdo do documento" data-placeholder="Comece uma história…">${sanitize(note.body)}</div><div class="editor-bottom"><span id="wordCount"></span><span id="editingStatus">Modo de edição</span><button class="text-link" data-action="deleteNote">Excluir documento</button></div></article>`;}

